```systemverilog
module tag_tracker_tb;
  localparam int TAG_W = 3;
  localparam int SLOTS = 8;
  localparam int N_MATCH = 1;
  typedef logic [31:0] pl_t;

  logic clk;
  initial begin clk = 1'b0; forever #5 clk = ~clk; end
  logic rst_n;
  initial rst_n = 1'b0;
  task automatic bfm_reset(input int cycles = 4);
    @(negedge clk); rst_n = 1'b0;
    repeat (cycles) @(posedge clk);
    @(negedge clk); rst_n = 1'b1;
  endtask
  task automatic bfm_drive_point(); @(negedge clk); endtask
  task automatic bfm_tick(); @(posedge clk); endtask
  initial begin #20_000_000; $display("RESULT: FAIL (watchdog)"); $finish; end

  // DUT signals
  logic [TAG_W-1:0] push_tag, pop_tag;
  pl_t push_data, pop_data;
  logic push_req, push_gnt, pop_en, pop_req, pop_gnt, pop_valid;
  pl_t [N_MATCH-1:0] match_data, match_mask;
  logic [N_MATCH-1:0] match_req, match_hit, match_gnt;
