  task automatic do_match(input pl_t data, input pl_t mask);
    automatic int tries = 0;
    automatic bit granted = 0, aborted = 0;
    automatic bit exp_hit = 0;
    begin
      match_data[0] = data; match_mask[0] = mask;
      @(negedge clk); match_req[0] = 1'b1;
      while (!granted && !aborted) begin
        @(posedge clk);
        if (match_gnt[0] === 1'b1) granted = 1;
        else begin tries++; if (tries>500) begin fail("R11","match never granted"); aborted=1; end end
